-- =========================================================================================
-- SARBAAZ FOOTWEAR POS - ENTERPRISE MULTI-STORE DATABASE IMPORT SCRIPT (.SQL)
-- File: /public/multi-store-pos-import.sql
-- Scale:
--   * 24 Deployed Stores (tenants) + 24 Store Settings (company_settings)
--   * 48 Store Staff Accounts (24 Owners + 24 Cashiers) + SuperAdmin
--   * 96 Categories
--   * 2,400 Unique Footwear SKUs (products) - 100 SKUs per store
--   * 96 Suppliers & 240 Customers
--   * 240 Purchases (POs), 480 Purchase Items, 120 Supplier Payments, 72 Purchase Returns
--   * 480 POS Sales Invoices, 960 Sale Items, 120 Customer Sales Returns
--   * 480 Stock Ledger Movements & Full PostgreSQL Sequence Synchronization
-- =========================================================================================

BEGIN;

-- Ensure all core schema tables exist before truncating/importing (safe for empty databases)
CREATE TABLE IF NOT EXISTS tenants (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  subscription_plan TEXT NOT NULL DEFAULT 'YEARLY',
  subscription_start_date TIMESTAMP NOT NULL DEFAULT NOW(),
  subscription_end_date TIMESTAMP NOT NULL DEFAULT (NOW() + INTERVAL '1 year'),
  subscription_status TEXT NOT NULL DEFAULT 'ACTIVE',
  theme_color TEXT NOT NULL DEFAULT '#2563EB',
  background_color TEXT NOT NULL DEFAULT '#ffffff',
  onboarding_completed BOOLEAN NOT NULL DEFAULT false,
  deleted_product_ids INTEGER[] NOT NULL DEFAULT '{}',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS store_requests (
  id SERIAL PRIMARY KEY,
  store_name TEXT NOT NULL,
  owner_email TEXT NOT NULL,
  owner_phone TEXT DEFAULT '',
  business_address TEXT DEFAULT '',
  plan TEXT NOT NULL DEFAULT 'PRO',
  request_type TEXT NOT NULL DEFAULT 'NEW_STORE',
  notes TEXT DEFAULT '',
  status TEXT NOT NULL DEFAULT 'PENDING',
  provisioned_tenant_id INTEGER REFERENCES tenants(id) ON DELETE SET NULL,
  initial_password TEXT DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS deleted_store_requests (
  id SERIAL PRIMARY KEY,
  request_id INTEGER,
  marker_key TEXT NOT NULL DEFAULT '',
  deleted_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT DEFAULT '',
  avatar_url TEXT DEFAULT '',
  password_hash TEXT NOT NULL,
  quick_password TEXT DEFAULT '',
  role TEXT NOT NULL DEFAULT 'CASHIER',
  status TEXT NOT NULL DEFAULT 'PENDING',
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS company_settings (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  logo TEXT DEFAULT '',
  address TEXT DEFAULT '',
  phone TEXT DEFAULT '',
  email TEXT DEFAULT '',
  website TEXT DEFAULT '',
  strn TEXT DEFAULT '',
  tax_id TEXT DEFAULT '',
  tax_rate NUMERIC(5, 2) NOT NULL DEFAULT 0.00,
  currency TEXT NOT NULL DEFAULT 'PKR',
  currency_name TEXT NOT NULL DEFAULT 'Pakistani Rupee',
  currency_symbol TEXT NOT NULL DEFAULT 'Rs.',
  invoice_prefix TEXT NOT NULL DEFAULT 'INV-',
  purchase_prefix TEXT NOT NULL DEFAULT 'PUR-',
  barcode_prefix TEXT NOT NULL DEFAULT '',
  invoice_footer TEXT NOT NULL DEFAULT 'Thank you for shopping with us!',
  show_receipt_logo BOOLEAN NOT NULL DEFAULT false,
  receipt_logo TEXT DEFAULT '',
  low_stock_limit INTEGER NOT NULL DEFAULT 5,
  pricing_mode TEXT NOT NULL DEFAULT 'FIXED',
  pricing_policy_locked BOOLEAN NOT NULL DEFAULT false,
  is_installed BOOLEAN DEFAULT false,
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS categories (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  name TEXT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS products (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  tenant_product_no INTEGER,
  name TEXT NOT NULL,
  brand VARCHAR(100) NOT NULL DEFAULT 'Local',
  category VARCHAR(100) NOT NULL DEFAULT 'Men',
  sku TEXT NOT NULL,
  barcode TEXT NOT NULL,
  article TEXT DEFAULT '',
  primary_image_url TEXT DEFAULT '',
  description TEXT DEFAULT '',
  cost_price NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
  min_price INTEGER NOT NULL DEFAULT 0,
  max_price INTEGER NOT NULL DEFAULT 0,
  pricing_policy TEXT DEFAULT NULL,
  total_stock INTEGER NOT NULL DEFAULT 0,
  low_stock_limit INTEGER NOT NULL DEFAULT 5,
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS customers (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  email TEXT,
  address TEXT,
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS suppliers (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  name TEXT NOT NULL,
  phone TEXT DEFAULT '',
  email TEXT DEFAULT '',
  balance NUMERIC(12, 2) DEFAULT 0.00,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS purchases (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  purchase_number TEXT NOT NULL,
  supplier_id INTEGER REFERENCES suppliers(id) ON DELETE SET NULL,
  supplier_name TEXT NOT NULL,
  purchase_date TEXT NOT NULL,
  total_amount NUMERIC(12, 2) NOT NULL,
  paid_amount NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
  payment_status TEXT NOT NULL DEFAULT 'UNPAID',
  payment_method TEXT DEFAULT 'CASH',
  notes TEXT,
  created_by INTEGER NOT NULL REFERENCES users(id),
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS purchase_items (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  purchase_id INTEGER NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,
  product_id INTEGER NOT NULL REFERENCES products(id),
  quantity INTEGER NOT NULL,
  unit_purchase_price NUMERIC(12, 2) NOT NULL,
  subtotal NUMERIC(12, 2) NOT NULL
);

CREATE TABLE IF NOT EXISTS supplier_payments (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  payment_number TEXT NOT NULL,
  supplier_id INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,
  supplier_name TEXT NOT NULL,
  purchase_id INTEGER REFERENCES purchases(id) ON DELETE SET NULL,
  amount NUMERIC(12, 2) NOT NULL,
  payment_date TEXT NOT NULL,
  payment_method TEXT NOT NULL DEFAULT 'CASH',
  reference_number TEXT DEFAULT '',
  notes TEXT DEFAULT '',
  created_by INTEGER NOT NULL REFERENCES users(id),
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS purchase_returns (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  return_number TEXT NOT NULL,
  purchase_id INTEGER REFERENCES purchases(id) ON DELETE SET NULL,
  supplier_id INTEGER REFERENCES suppliers(id) ON DELETE SET NULL,
  supplier_name TEXT NOT NULL,
  return_date TEXT NOT NULL,
  total_debit_amount NUMERIC(12, 2) NOT NULL,
  reason TEXT NOT NULL,
  notes TEXT,
  created_by INTEGER NOT NULL REFERENCES users(id),
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS purchase_return_items (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  purchase_return_id INTEGER NOT NULL REFERENCES purchase_returns(id) ON DELETE CASCADE,
  product_id INTEGER NOT NULL REFERENCES products(id),
  quantity INTEGER NOT NULL,
  unit_purchase_price NUMERIC(12, 2) NOT NULL,
  subtotal NUMERIC(12, 2) NOT NULL,
  defect_type TEXT DEFAULT 'MANUFACTURING_DEFECT'
);

CREATE TABLE IF NOT EXISTS sales (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  invoice_number TEXT NOT NULL,
  customer_id INTEGER REFERENCES customers(id) ON DELETE SET NULL,
  sale_date TEXT NOT NULL,
  subtotal NUMERIC(12, 2) NOT NULL,
  discount NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
  total_amount NUMERIC(12, 2) NOT NULL,
  payment_method TEXT NOT NULL DEFAULT 'CASH',
  cash_received NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
  change_given NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
  created_by INTEGER NOT NULL REFERENCES users(id),
  is_min_price_overridden BOOLEAN NOT NULL DEFAULT false,
  overridden_by INTEGER REFERENCES users(id),
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sale_items (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  sale_id INTEGER NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
  product_id INTEGER NOT NULL REFERENCES products(id),
  product_name TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  unit_price NUMERIC(12, 2) NOT NULL,
  discount NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
  subtotal NUMERIC(12, 2) NOT NULL,
  purchase_price NUMERIC(12, 2) NOT NULL
);

CREATE TABLE IF NOT EXISTS returns (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  return_number TEXT NOT NULL,
  original_sale_id INTEGER NOT NULL REFERENCES sales(id),
  customer_id INTEGER REFERENCES customers(id) ON DELETE SET NULL,
  return_date TEXT NOT NULL,
  total_refund_amount NUMERIC(12, 2) NOT NULL,
  reason TEXT NOT NULL,
  created_by INTEGER NOT NULL REFERENCES users(id),
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS return_items (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  return_id INTEGER NOT NULL REFERENCES returns(id) ON DELETE CASCADE,
  sale_item_id INTEGER NOT NULL REFERENCES sale_items(id),
  product_id INTEGER NOT NULL REFERENCES products(id),
  quantity INTEGER NOT NULL,
  unit_refund_price NUMERIC(12, 2) NOT NULL,
  subtotal NUMERIC(12, 2) NOT NULL
);

CREATE TABLE IF NOT EXISTS stock_movements (
  id SERIAL PRIMARY KEY,
  tenant_id INTEGER NOT NULL DEFAULT 1,
  product_id INTEGER NOT NULL REFERENCES products(id),
  qty_change INTEGER NOT NULL,
  prev_stock INTEGER NOT NULL,
  new_stock INTEGER NOT NULL,
  movement_type TEXT NOT NULL,
  reference_id TEXT,
  user_id INTEGER NOT NULL REFERENCES users(id),
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

TRUNCATE TABLE
  password_reset_tokens,
  stock_movements,
  return_items,
  returns,
  sale_items,
  sales,
  purchase_return_items,
  purchase_returns,
  supplier_payments,
  purchase_items,
  purchases,
  products,
  customers,
  suppliers,
  categories,
  company_settings,
  store_requests
RESTART IDENTITY CASCADE;

DELETE FROM users WHERE UPPER(COALESCE(role, '')) != 'SUPERADMIN';
DELETE FROM tenants;

-- Ensure Platform SuperAdmin exists with password superadmin123
SELECT 1, 1, 'Platform SuperAdmin', 'talhah.jan@gmail.com', '+92-300-0000001', '$2b$10$7t3O9vYEMVeZ.VJsNDEf6eQ1xaQEQHEEf16nuz3GmbQcikzNRMCAK', 'superadmin123', 'SUPERADMIN', 'APPROVED', true, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM users WHERE UPPER(role) = 'SUPERADMIN');
UPDATE users SET password_hash = '$2b$10$7t3O9vYEMVeZ.VJsNDEf6eQ1xaQEQHEEf16nuz3GmbQcikzNRMCAK', quick_password = 'superadmin123', status = 'APPROVED', active = true WHERE UPPER(role) = 'SUPERADMIN';

-- 1. DEPLOYED STORES (24 TENANTS)

-- 2. STORE REQUESTS

-- 3. STORE SETTINGS (24 STORES)

-- 4. STORE USERS (24 OWNERS + 24 CASHIERS)

-- 5. CATEGORIES

-- 6. PRODUCTS / SKUs (2,400 FOOTWEAR SKUs ACROSS 24 STORES)






-- 7. SUPPLIERS (96) & CUSTOMERS (240)


-- 8. PURCHASES (240 POs), PURCHASE ITEMS (480), SUPPLIER PAYMENTS (120) & PURCHASE RETURNS (72)





-- 9. POS SALES (480 INVOICES), SALE ITEMS (960) & CUSTOMER RETURNS (120)





-- 10. SYNCHRONIZE ALL POSTGRESQL SERIAL SEQUENCES
SELECT setval(pg_get_serial_sequence('tenants', 'id'), COALESCE((SELECT MAX(id) FROM tenants), 1));
SELECT setval(pg_get_serial_sequence('store_requests', 'id'), COALESCE((SELECT MAX(id) FROM store_requests), 1));
SELECT setval(pg_get_serial_sequence('company_settings', 'id'), COALESCE((SELECT MAX(id) FROM company_settings), 1));
SELECT setval(pg_get_serial_sequence('users', 'id'), COALESCE((SELECT MAX(id) FROM users), 1));
SELECT setval(pg_get_serial_sequence('categories', 'id'), COALESCE((SELECT MAX(id) FROM categories), 1));
SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX(id) FROM products), 1));
SELECT setval(pg_get_serial_sequence('suppliers', 'id'), COALESCE((SELECT MAX(id) FROM suppliers), 1));
SELECT setval(pg_get_serial_sequence('customers', 'id'), COALESCE((SELECT MAX(id) FROM customers), 1));
SELECT setval(pg_get_serial_sequence('purchases', 'id'), COALESCE((SELECT MAX(id) FROM purchases), 1));
SELECT setval(pg_get_serial_sequence('purchase_items', 'id'), COALESCE((SELECT MAX(id) FROM purchase_items), 1));
SELECT setval(pg_get_serial_sequence('supplier_payments', 'id'), COALESCE((SELECT MAX(id) FROM supplier_payments), 1));
SELECT setval(pg_get_serial_sequence('purchase_returns', 'id'), COALESCE((SELECT MAX(id) FROM purchase_returns), 1));
SELECT setval(pg_get_serial_sequence('purchase_return_items', 'id'), COALESCE((SELECT MAX(id) FROM purchase_return_items), 1));
SELECT setval(pg_get_serial_sequence('sales', 'id'), COALESCE((SELECT MAX(id) FROM sales), 1));
SELECT setval(pg_get_serial_sequence('sale_items', 'id'), COALESCE((SELECT MAX(id) FROM sale_items), 1));
SELECT setval(pg_get_serial_sequence('returns', 'id'), COALESCE((SELECT MAX(id) FROM returns), 1));
SELECT setval(pg_get_serial_sequence('return_items', 'id'), COALESCE((SELECT MAX(id) FROM return_items), 1));
SELECT setval(pg_get_serial_sequence('stock_movements', 'id'), COALESCE((SELECT MAX(id) FROM stock_movements), 1));

COMMIT;
